#include <iostream>

// Returns the square of an integer
int square(int x) {
    return x * x; // Computes square and returns to caller
}

int main() {
    int a = 10; // Automatic local variable in main's stack frame
    std::cout << a << " squared: " << square(a) << "\n";
    return 0;
}

#include <iostream>
#include <cctype>
#include <climits>
#include <cfloat>

int main() {
    // Inspect character using functions from <cctype> (legacy <ctype.h>)
    char ch = 'g';
    std::cout << "Is alpha: " << (std::isalpha(ch) ? 1 : 0) << "\n";
    std::cout << "Uppercase: " << static_cast<char>(std::toupper(ch)) << "\n";

    // Inspect numerical limits from <climits> and <cfloat>
    std::cout << "INT_MAX: " << INT_MAX << "\n";
